global.afterNatural=fp('02-after-natural-and-controls');await check('RFQ snapshots unchanged by UI/download trials',afterNatural,seed);
await cdp.send('Debugger.enable');await installGate();p.on('console',m=>{if(m.text().startsWith('__OBS_FLAGS__'))rec('ui-state-flags',JSON.parse(m.text().slice(13)))});for(const sc of scripts){if(sc.url==='http://127.0.0.1:8990/'){const ss=await cdp.send('Debugger.getScriptSource',{scriptId:sc.scriptId});const aa=ss.scriptSource.split('\n');const ix=aa.findIndex(l=>l.includes('saveBtn.disabled=!buyerMode||busy||!localReady||blocked;'));if(ix>=0){const q=await cdp.send('Debugger.setBreakpoint',{location:{scriptId:sc.scriptId,lineNumber:sc.startLine+ix},condition:'(console.debug("__OBS_FLAGS__"+JSON.stringify({date:new Date().toISOString(),mono:performance.now(),trialAtEvent:window.__obsTrial,busy,dirty,blocked,s4Available})),false)'});rec('flags-logpoint-installed',{location:q.actualLocation,sourceLine:aa[ix]});break}}}
await p.evaluate(()=>window.addEventListener('srm:workspace-saved',e=>window.__obsEmit({trialAtEvent:window.__obsTrial,event:'workspace-saved',detail:e.detail,state:window.__obsState()})));global.addTestItem=async code=>{await p.locator('[data-srm-v2-tab="items"]').click();if(!await p.locator('#itemIntake').isVisible())await p.locator('#toggleItemIntake').click();await p.locator('#manualCode').fill(code);await p.locator('#manualName').fill('完全虚构自动保存时序诊断件');await p.locator('#manualQty').fill('2');await p.locator('#manualUnit').fill('件');await p.locator('#manualAdd').click();await p.locator('#confirmImportRows').click()};
await switchTo(idB,250);await switchTo(idA,1500);global.slowPut=false;await p.route('**/api/workspaces/*',async route=>{if(route.request().method()==='PUT'&&!slowPut){slowPut=true;rec('controlled-network-delay',{route:route.request().url(),delayMs:3000,purpose:'Observe an existing auto-save in flight, no response corruption or product mutation'});await new Promise(r=>setTimeout(r,3000));}await route.continue()});let waitPut=p.waitForRequest(q=>q.method()==='PUT'&&q.url().includes('/api/workspaces/'));await addTestItem('OBS01-AUTO-SLOW');await waitPut;await p.locator('[data-srm-v2-action="admin"]').click();await p.locator('#pilotS4DownloadFull').scrollIntoViewIfNeeded();await check('S01 backup disabled during actual delayed autosave',await p.locator('#pilotS4DownloadFull').isDisabled(),true);await attempt('S01','controlled-3000ms-auto-save-in-flight-disabled-click','mouse',1000);await p.unroute('**/api/workspaces/*');await p.waitForFunction(()=>document.querySelector('#pilotAutosaveStatus').textContent.includes('已自动保存'));await settled();await attempt('S02','same-state-after-delayed-autosave-completes');
await switchTo(idB,250);await switchTo(idA,1500);let saved=p.waitForEvent('response',{predicate:q=>q.request().method()==='PUT'&&q.url().includes('/api/workspaces/')&&q.status()===200});await addTestItem('OBS01-AUTO-NATURAL');await saved;await p.waitForFunction(()=>document.querySelector('#pilotAutosaveStatus').textContent.includes('已自动保存'));await p.locator('[data-srm-v2-action="admin"]').click();await attempt('S03','natural-autosave-just-completed-admin-immediate');await p.waitForTimeout(1000);await attempt('S04','retry-after-one-poll-no-business-change');global.last=fp('02-final');await check('original other RFQ untouched',last.workspaces[idB],seed.workspaces[idB]);await check('only two RFQs present',Object.keys(last.workspaces).length,2);console.log('ALL_22_ATTEMPTS_EXECUTED');

global.seed=JSON.parse(fs.readFileSync(root+'01-seed.json'));global.idA=Object.entries(seed.workspaces).find(([k,v])=>v.snapshot.state.items.length>0)[0];global.idB=Object.entries(seed.workspaces).find(([k,v])=>!v.snapshot.state.items.length)[0];global.fastSamples=true;global.attempt=eval('('+attempt.toString().replace("await shot(id+'-before');","if(!global.fastSamples)await shot(id+'-before');")+')');global.switchTo=async(id,delay=0)=>{await openD('#uiProjectDetails');await p.locator('#pilotHistoryWorkspace').selectOption(id);await p.locator('#pilotSwitchWorkspace').click();await p.waitForFunction(id=>window.SRMPilot.snapshot()?.workspaceId===id,id);await p.waitForFunction(()=>!document.querySelector('#pilotHistoryWorkspace').disabled);if(delay)await p.waitForTimeout(delay);rec('switch-complete',{id,state:await state()})};
await installGate();global.resumed=fp('03-after-harness-resume');await check('B untouched after harness failure',resumed.workspaces[idB],seed.workspaces[idB]);await check('A auto-save completed before harness failure',resumed.workspaces[idA].snapshot.state.items.map(x=>x.id),['OBS01-FICTIONAL','OBS01-AUTO-SLOW']);global.addTestItem=async code=>{await p.locator('[data-srm-v2-tab="items"]').click();if(!await p.locator('#itemIntake').isVisible())await p.locator('#toggleItemIntake').click();await p.locator('#manualCode').fill(code);await p.locator('#manualName').fill('完全虚构自动保存时序诊断件');await p.locator('#manualQty').fill('2');await p.locator('#manualUnit').fill('件');await p.locator('#manualAdd').click();await p.locator('#confirmImportRows').click()};
await switchTo(idA,1500);let saved=p.waitForResponse(q=>q.request().method()==='PUT'&&q.url().includes('/api/workspaces/')&&q.status()===200);await addTestItem('OBS01-AUTO-NATURAL');await saved;await p.waitForFunction(()=>document.querySelector('#pilotAutosaveStatus').textContent.includes('已自动保存'));await p.locator('[data-srm-v2-action="admin"]').click();await attempt('S03','natural-autosave-just-completed-admin-immediate');await p.waitForTimeout(1000);await attempt('S04','retry-after-one-poll-no-business-change');
await run('direct-control.js');for(const [id,delay]of [['R01',0],['R02',1000]]){await switchTo(idB,250);await switchTo(idA,1500);await p.locator('[data-srm-v2-action="admin"]').click();if(delay)await p.waitForTimeout(delay);await attempt(id,delay?'same-header-path-wait1000ms-trace-control':'header-immediate-trace-reproduction');}
